$y = \sqrt{x^2 - 3x} = (x^2 - 3x)^{\frac{1}{2}}$
$\therefore \frac{dy}{dx} = \frac{1}{2}(x^2 - 3x)^{-\frac{1}{2}}(2x - 3) \quad \{\text{chain rule}\}
= \frac{2x - 3}{2\sqrt{x^2 - 3x}}$

$y = \sqrt{x + \frac{1}{x^2} + 1} = (x + x^{-2} + 1)^{\frac{1}{2}}$
$\therefore \frac{dy}{dx} = \frac{1}{2}(x + x^{-2} + 1)^{-\frac{1}{2}} \times (1 - 2x^{-3}) \quad \{\text{chain rule}\}
= \frac{1 - \frac{2}{x^3}}{2\sqrt{x + \frac{1}{x^2} + 1}}$

When $x = 4$,
$\frac{dy}{dx} = \frac{1 - \frac{2}{4^3}}{2\sqrt{4 + \frac{1}{4^2} + 1}}
= \frac{1 - \frac{2}{64}}{2\sqrt{5 + \frac{1}{16}}}
= \frac{\frac{31}{32}}{2\sqrt{\frac{81}{16}}}
= \frac{\frac{31}{32}}{2 \times \frac{9}{4}}
= \frac{31}{2 \times 32} \times \frac{4}{9}
= \frac{31}{144}$

So, the tangent has gradient $\frac{31}{144}$.

$y = x^2\sqrt{x^2 + 2x} = x^2(x^2 + 2x)^{\frac{1}{2}}$
$\therefore \frac{dy}{dx} = 2x(x^2 + 2x)^{\frac{1}{2}} + x^2 \times \frac{1}{2}(x^2 + 2x)^{-\frac{1}{2}}(2x + 2) \quad \{\text{product rule}\}
= 2x\sqrt{x^2 + 2x} + \frac{x^2(x + 1)}{\sqrt{x^2 + 2x}}$

$y = \sqrt{x}(2x + 3)^4 = x^{\frac{1}{2}}(2x + 3)^4$
$\therefore \frac{dy}{dx} = \frac{1}{2}x^{-\frac{1}{2}}(2x + 3)^4 + x^{\frac{1}{2}} \times 4(2x + 3)^3(2) \quad \{\text{product rule}\}
= \frac{(2x + 3)^4}{2\sqrt{x}} + 8\sqrt{x}(2x + 3)^3$

$f(x) = \frac{\sqrt{x}}{x - 3} = \frac{x^{\frac{1}{2}}}{x - 3}$
$\therefore f'(x) = \frac{\frac{1}{2}x^{-\frac{1}{2}}(x - 3) - (1)x^{\frac{1}{2}}}{(x - 3)^2} \quad \{\text{quotient rule}\}
= \frac{x - 3 - 2x}{2\sqrt{x}(x - 3)^2}
= \frac{-3 - x}{2\sqrt{x}(x - 3)^2}$

$f(t) = \frac{100}{1 + 7e^{-\frac{t}{4}}} = 100\left(1 + 7e^{-\frac{t}{4}}\right)^{-1}$
$\therefore f'(t) = -100\left(1 + 7e^{-\frac{t}{4}}\right)^{-2} \times \left(-\frac{7}{4}e^{-\frac{t}{4}}\right) \quad \{\text{chain rule}\}
= \frac{175e^{-\frac{t}{4}}}{\left(1 + 7e^{-\frac{t}{4}}\right)^2}$

$f(t) = \frac{t + 9}{e^t}$
$\therefore f'(t) = \frac{(1)e^t - e^t(t + 9)}{(e^t)^2} \quad \{\text{quotient rule}\}
= \frac{1 - (t + 9)}{e^t}
= \frac{-t - 8}{e^t}$
